import { decodeAgentRenameRequest, type AgentConversationSummary } from "@research-assistant/core/agent";
import { getAppStorage } from "../../runtime/appStorage";
import { acquireConversationRenameOwner, renameUnresolved, type ConversationRenamePorts } from "./conversationRenameController";
import { summarizeConversationTitle } from "./presentation/writingConversationTitle";

/** Naming is a separate phase of an accepted message. Its UUID is generated
 * once and persisted, never borrowed from the model request or regenerated by
 * an IPC retry. No failure here can resubmit the accepted model invocation. */
export async function nameInitialConversation(id: string, sourceRequestId: string, text: string,
  ports: ConversationRenamePorts, storage: Storage = getAppStorage()): Promise<AgentConversationSummary | null> {
  const title = summarizeConversationTitle(text);
  if (title === "新对话") return null;
  const lease = acquireConversationRenameOwner(id, ports, storage);
  try {
    if (renameUnresolved(lease.controller.getSnapshot())) return null;
    const key = `research-assistant:initial-conversation-name:v1:${id.toLowerCase()}:${sourceRequestId}`;
    const raw = storage.getItem(key);
    const previous: unknown = raw === null ? null : JSON.parse(raw);
    if (raw !== null && (!previous || typeof previous !== "object" || !("schemaVersion" in previous)
      || previous.schemaVersion !== 1 || !("sourceRequestId" in previous)
      || previous.sourceRequestId !== sourceRequestId || !("intent" in previous))) throw new Error("RENAME_RECOVERY_INVALID");
    const intent = raw !== null ? decodeAgentRenameRequest((previous as { intent: unknown }).intent) : decodeAgentRenameRequest({
      operationId: crypto.randomUUID(), id, expectedTitle: "新对话", title,
    });
    if (intent.id !== id.toLowerCase()) throw new Error("RENAME_RECOVERY_INVALID");
    if (raw === null) storage.setItem(key, JSON.stringify({ schemaVersion: 1, sourceRequestId, intent }));
    const current = await lease.controller.submitIntent(intent);
    if (!current && lease.controller.getSnapshot().phase === "rejected") throw lease.controller.getSnapshot().cause;
    return current;
  } finally { lease.release(); }
}
